CREATE TYPE public.app_role AS ENUM ('professional','employer','admin');
CREATE TABLE public.user_roles(user_id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE, role public.app_role NOT NULL DEFAULT 'professional');
GRANT SELECT ON public.user_roles TO authenticated; GRANT ALL ON public.user_roles TO service_role;
ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_role ON public.user_roles FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE FUNCTION public.has_role(_user_id uuid,_role public.app_role) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path='' AS $$ SELECT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=_user_id AND role=_role) $$;
REVOKE ALL ON FUNCTION public.has_role(uuid,public.app_role) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.has_role(uuid,public.app_role) TO authenticated;
CREATE TABLE public.profiles(id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE, full_name text NOT NULL DEFAULT '', professional_title text NOT NULL DEFAULT '', location text NOT NULL DEFAULT '', languages text[] NOT NULL DEFAULT '{}', biography text NOT NULL DEFAULT '', professional_category text NOT NULL DEFAULT 'Technology', portfolio_links text[] NOT NULL DEFAULT '{}', profile_visibility text NOT NULL DEFAULT 'private' CHECK(profile_visibility IN ('private','directory')), employer_directory_consent boolean NOT NULL DEFAULT false, passport_sharing boolean NOT NULL DEFAULT false, share_assessments boolean NOT NULL DEFAULT false, passport_id uuid NOT NULL UNIQUE DEFAULT gen_random_uuid(), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,UPDATE ON public.profiles TO authenticated; GRANT ALL ON public.profiles TO service_role;
ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_profile_read ON public.profiles FOR SELECT TO authenticated USING(id=auth.uid());
CREATE POLICY own_profile_edit ON public.profiles FOR UPDATE TO authenticated USING(id=auth.uid()) WITH CHECK(id=auth.uid());
CREATE FUNCTION public.touch_updated_at() RETURNS trigger LANGUAGE plpgsql SET search_path='' AS $$ BEGIN NEW.updated_at=now(); RETURN NEW; END $$;
CREATE TRIGGER profile_updated BEFORE UPDATE ON public.profiles FOR EACH ROW EXECUTE FUNCTION public.touch_updated_at();
CREATE FUNCTION public.create_bridge_profile() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$ BEGIN INSERT INTO public.profiles(id,full_name) VALUES(NEW.id,coalesce(NEW.raw_user_meta_data->>'full_name','')); INSERT INTO public.user_roles(user_id,role) VALUES(NEW.id,CASE WHEN NEW.raw_user_meta_data->>'account_type'='employer' THEN 'employer'::public.app_role ELSE 'professional'::public.app_role END); RETURN NEW; END $$;
REVOKE ALL ON FUNCTION public.create_bridge_profile() FROM PUBLIC;
CREATE TRIGGER bridge_signup AFTER INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION public.create_bridge_profile();
CREATE TABLE public.experiences(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE, job_title text NOT NULL, organization text NOT NULL DEFAULT '', description text NOT NULL DEFAULT '', start_date date, end_date date, created_at timestamptz NOT NULL DEFAULT now(), CHECK(end_date IS NULL OR start_date IS NULL OR end_date>=start_date));
GRANT SELECT,INSERT,UPDATE,DELETE ON public.experiences TO authenticated; GRANT ALL ON public.experiences TO service_role; ALTER TABLE public.experiences ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_experiences ON public.experiences TO authenticated USING(user_id=auth.uid()) WITH CHECK(user_id=auth.uid()); CREATE INDEX experiences_owner ON public.experiences(user_id);
CREATE TABLE public.qualifications(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE, qualification_name text NOT NULL, institution text NOT NULL DEFAULT '', completion_year integer CHECK(completion_year BETWEEN 1900 AND 2100), verification_status text NOT NULL DEFAULT 'self-reported' CHECK(verification_status IN ('self-reported','evidence submitted','independently reviewed')), evidence_reference text NOT NULL DEFAULT '', created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.qualifications TO authenticated; GRANT ALL ON public.qualifications TO service_role; ALTER TABLE public.qualifications ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_qualifications ON public.qualifications TO authenticated USING(user_id=auth.uid()) WITH CHECK(user_id=auth.uid()); CREATE INDEX qualifications_owner ON public.qualifications(user_id);
CREATE TABLE public.skills(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE, skill_name text NOT NULL, skill_category text NOT NULL DEFAULT 'Technical', proficiency_level text NOT NULL DEFAULT 'Developing' CHECK(proficiency_level IN ('Developing','Confident','Very confident')), evidence_description text NOT NULL DEFAULT '', assessment_status text NOT NULL DEFAULT 'self-reported' CHECK(assessment_status IN ('self-reported','evidence submitted','independently reviewed')), created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.skills TO authenticated; GRANT ALL ON public.skills TO service_role; ALTER TABLE public.skills ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_skills ON public.skills TO authenticated USING(user_id=auth.uid()) WITH CHECK(user_id=auth.uid()); CREATE INDEX skills_owner ON public.skills(user_id);
CREATE FUNCTION public.protect_review_status() RETURNS trigger LANGUAGE plpgsql SET search_path='' AS $$ BEGIN IF coalesce(auth.role(),'')='service_role' OR public.has_role(auth.uid(),'admin') THEN RETURN NEW; END IF; IF TG_TABLE_NAME='qualifications' THEN IF NEW.verification_status='independently reviewed' THEN RAISE EXCEPTION 'Independent review requires an authorized reviewer'; END IF; ELSE IF NEW.assessment_status='independently reviewed' THEN RAISE EXCEPTION 'Independent review requires an authorized reviewer'; END IF; END IF; RETURN NEW; END $$;
CREATE TRIGGER protect_qualification_review BEFORE INSERT OR UPDATE ON public.qualifications FOR EACH ROW EXECUTE FUNCTION public.protect_review_status();
CREATE TRIGGER protect_skill_review BEFORE INSERT OR UPDATE ON public.skills FOR EACH ROW EXECUTE FUNCTION public.protect_review_status();
CREATE TABLE public.assessments(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE, assessment_category text NOT NULL DEFAULT 'Professional strengths', answers jsonb NOT NULL, results jsonb NOT NULL, completion_status text NOT NULL DEFAULT 'complete', completed_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.assessments TO authenticated; GRANT ALL ON public.assessments TO service_role; ALTER TABLE public.assessments ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_assessments ON public.assessments TO authenticated USING(user_id=auth.uid()) WITH CHECK(user_id=auth.uid()); CREATE INDEX assessments_owner ON public.assessments(user_id);
CREATE TABLE public.analysis_results(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE, submitted_experience text NOT NULL, extracted_skills jsonb NOT NULL DEFAULT '[]', strengths jsonb NOT NULL DEFAULT '[]', growth_areas jsonb NOT NULL DEFAULT '[]', recommendations jsonb NOT NULL DEFAULT '[]', summary text NOT NULL DEFAULT '', evidence_suggestions jsonb NOT NULL DEFAULT '[]', created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.analysis_results TO authenticated; GRANT ALL ON public.analysis_results TO service_role; ALTER TABLE public.analysis_results ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_analysis ON public.analysis_results TO authenticated USING(user_id=auth.uid()) WITH CHECK(user_id=auth.uid()); CREATE INDEX analysis_owner ON public.analysis_results(user_id);
CREATE TABLE public.learning_pathways(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), title text NOT NULL UNIQUE, category text NOT NULL, provider text NOT NULL, description text NOT NULL, duration text NOT NULL, difficulty text NOT NULL, external_url text, illustrative boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.learning_pathways TO anon,authenticated; GRANT ALL ON public.learning_pathways TO service_role; ALTER TABLE public.learning_pathways ENABLE ROW LEVEL SECURITY;
CREATE POLICY read_pathways ON public.learning_pathways FOR SELECT TO anon,authenticated USING(true);
CREATE TABLE public.saved_pathways(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE, pathway_id uuid NOT NULL REFERENCES public.learning_pathways(id) ON DELETE CASCADE, progress_status text NOT NULL DEFAULT 'saved' CHECK(progress_status IN ('saved','in progress','completed')), created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(user_id,pathway_id));
GRANT SELECT,INSERT,UPDATE,DELETE ON public.saved_pathways TO authenticated; GRANT ALL ON public.saved_pathways TO service_role; ALTER TABLE public.saved_pathways ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_saved_pathways ON public.saved_pathways TO authenticated USING(user_id=auth.uid()) WITH CHECK(user_id=auth.uid()); CREATE INDEX saved_owner ON public.saved_pathways(user_id);
CREATE FUNCTION public.safe_passport(_id uuid) RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path='' AS $$ SELECT jsonb_build_object('full_name',p.full_name,'professional_title',p.professional_title,'location',p.location,'languages',p.languages,'biography',p.biography,'professional_category',p.professional_category,'portfolio_links',p.portfolio_links,'passport_id',p.passport_id,'updated_at',p.updated_at,'skills',coalesce((SELECT jsonb_agg(jsonb_build_object('skill_name',s.skill_name,'skill_category',s.skill_category,'proficiency_level',s.proficiency_level,'assessment_status',s.assessment_status)) FROM public.skills s WHERE s.user_id=p.id),'[]'::jsonb),'experiences',coalesce((SELECT jsonb_agg(jsonb_build_object('job_title',e.job_title,'organization',e.organization,'description',e.description,'start_date',e.start_date,'end_date',e.end_date)) FROM public.experiences e WHERE e.user_id=p.id),'[]'::jsonb),'qualifications',coalesce((SELECT jsonb_agg(jsonb_build_object('qualification_name',q.qualification_name,'institution',q.institution,'completion_year',q.completion_year,'verification_status',q.verification_status)) FROM public.qualifications q WHERE q.user_id=p.id),'[]'::jsonb),'assessments',CASE WHEN p.share_assessments THEN coalesce((SELECT jsonb_agg(jsonb_build_object('results',a.results,'completed_at',a.completed_at)) FROM public.assessments a WHERE a.user_id=p.id),'[]'::jsonb) ELSE '[]'::jsonb END) FROM public.profiles p WHERE p.id=_id $$;
REVOKE ALL ON FUNCTION public.safe_passport(uuid) FROM PUBLIC,anon,authenticated;
CREATE FUNCTION public.public_passport(_passport_id uuid) RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path='' AS $$ SELECT public.safe_passport(p.id) FROM public.profiles p WHERE p.passport_id=_passport_id AND p.passport_sharing AND EXISTS(SELECT 1 FROM public.user_roles r WHERE r.user_id=p.id AND r.role='professional') $$;
REVOKE ALL ON FUNCTION public.public_passport(uuid) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.public_passport(uuid) TO anon,authenticated;
CREATE FUNCTION public.employer_directory() RETURNS SETOF jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path='' AS $$ SELECT public.safe_passport(p.id) FROM public.profiles p WHERE p.profile_visibility='directory' AND p.employer_directory_consent AND EXISTS(SELECT 1 FROM public.user_roles r WHERE r.user_id=p.id AND r.role='professional') AND (public.has_role(auth.uid(),'employer') OR public.has_role(auth.uid(),'admin')) $$;
REVOKE ALL ON FUNCTION public.employer_directory() FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.employer_directory() TO authenticated;
CREATE FUNCTION public.admin_statistics() RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path='' AS $$ BEGIN IF NOT public.has_role(auth.uid(),'admin') THEN RAISE EXCEPTION 'Administrator access required'; END IF; RETURN jsonb_build_object('profiles',(SELECT count(*) FROM public.profiles),'employers',(SELECT count(*) FROM public.user_roles WHERE role='employer'),'assessments',(SELECT count(*) FROM public.assessments),'saved_pathways',(SELECT count(*) FROM public.saved_pathways)); END $$;
REVOKE ALL ON FUNCTION public.admin_statistics() FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.admin_statistics() TO authenticated;